import os, sys

if sys.argv[1] == "preflight":
    paths = (".", "/var/tmp", "/dev/shm")
    if len({os.stat(p).st_dev for p in paths}) != len(paths):
        sys.exit("CONTROL-FAILED: fixture filesystems are not distinct")
    for parent in paths:
        path = os.path.join(parent, "link-control-probe")
        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        os.close(fd)
        os.unlink(path)
elif sys.argv[1] == "snapshot":
    for path in sys.argv[2:]:
        s = os.stat(path)
        with open(path, "rb") as f:
            data = f.read()
        print(path, s.st_dev, s.st_ino, s.st_mode, s.st_nlink,
              s.st_size, s.st_mtime_ns, data.hex())
else:
    raise SystemExit(98)
